import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { Search, Leaf, Tag, ArrowRight } from "lucide-react";
import {
    getAllSchemes,
    getByCategory,
    getByState
} from "../services/schemeService";

const SchemePage = () => {

    const [schemes, setSchemes] = useState([]);
    const [loading, setLoading] = useState(true);
    const [category, setCategory] = useState("");
    const [state, setState] = useState("");
    const [search, setSearch] = useState("");

    useEffect(() => {
        fetchSchemes();
    }, []);

    const fetchSchemes = async () => {
        try {
            const data = await getAllSchemes();
            setSchemes(data);
        } catch (error) {
            console.error(error);
        } finally {
            setLoading(false);
        }
    };

    const handleCategoryChange = async (e) => {
        const value = e.target.value;
        setCategory(value);
        setState("");

        if (value === "") {
            fetchSchemes();
        } else {
            const data = await getByCategory(value);
            setSchemes(data);
        }
    };

    const handleStateChange = async (e) => {
        const value = e.target.value;
        setState(value);
        setCategory("");

        if (value === "") {
            fetchSchemes();
        } else {
            const data = await getByState(value);
            setSchemes(data);
        }
    };

    const filteredSchemes = schemes.filter((scheme) =>
        scheme.schemeName.toLowerCase().includes(search.toLowerCase())
    );

    if (loading) return <h2 style={{ textAlign: "center" }}>Loading...</h2>;

    return (
        <div className="container">

            <h2 className="main-heading">
                <Leaf size={28} className="heading-icon" />
                KrushiSetu Government Schemes
            </h2>

            {/* SEARCH + FILTER */}
            <div className="filters">

                <div className="search-box">
                    <Search size={18} className="search-icon" />
                    <input
                        type="text"
                        placeholder="Search schemes..."
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                    />
                </div>

                <select value={category} onChange={handleCategoryChange}>
                    <option value="">Filter by Category</option>
                    <option value="Central Government">Central Government</option>
                    <option value="Insurance">Insurance</option>
                    <option value="Loan">Loan</option>
                    <option value="Solar">Solar</option>
                    <option value="Irrigation">Irrigation</option>
                    <option value="Subsidy">Subsidy</option>
                    <option value="Dairy">Dairy</option>
                    <option value="Poultry">Poultry</option>
                    <option value="Organic Farming">Organic Farming</option>
                    <option value="Horticulture">Horticulture</option>
                    <option value="Fisheries">Fisheries</option>
                    <option value="Warehouse">Warehouse</option>
                    <option value="Infrastructure">Infrastructure</option>
                    <option value="Women Farmer">Women Farmer</option>
                    <option value="SC/ST">SC/ST</option>
                    <option value="Cold Storage">Cold Storage</option>
                </select>

                <select value={state} onChange={handleStateChange}>
                    <option value="">Filter by State</option>
                    <option value="All India">All India</option>
                </select>

            </div>

            {/* CARDS */}
            <div className="grid">
                {filteredSchemes.length === 0 ? (
                    <p>No schemes found.</p>
                ) : (
                    filteredSchemes.map((scheme) => (
                        <div key={scheme.id} className="card">

                            <img
                                src={process.env.PUBLIC_URL + scheme.image}
                                alt={scheme.schemeName}
                            />

                            <div className="card-body">
                                <h3>{scheme.schemeName}</h3>

                                <p className="category-text">
                                    <Tag size={16} className="icon" />
                                    {scheme.category}
                                </p>

                                <p>
                                    {scheme.description?.substring(0, 90)}...
                                </p>

                                <Link to={`/scheme/${scheme.id}`} className="btn">
                                    View Details
                                    <ArrowRight size={16} className="btn-icon" />
                                </Link>
                            </div>
                        </div>
                    ))
                )}
            </div>
        </div>
    );
};

export default SchemePage;
